const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const W=960,H=540,GR=477;let state='title',level=1,score=0,lives=3,cam=0,frame=0,muted=false,shake=0;
let keys={},pressed={},player={},enemies=[],candies=[],shots=[],particles=[],platforms=[],worldW=2400,boss=null,gate=null,notice='',noticeT=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a);
function resize(){let dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}new ResizeObserver(resize).observe(canvas);resize();
function makeLevel(n){level=n;cam=0;worldW=n===3?2300:2450;player={x:75,y:GR-56,vx:0,vy:0,w:34,h:54,face:1,ground:false,inv:0,attack:0,sugar:0,anim:0};enemies=[];candies=[];shots=[];particles=[];boss=null;
platforms=[{x:0,y:GR,w:worldW,h:100,type:'ground'}];
for(let i=0;i<8;i++){let x=280+i*275+rand(-30,25),y=GR-rand(85,170);platforms.push({x,y,w:120+rand(0,55),h:18,type:'grass'});}
if(n===1){enemies=[['apple',390],['carrot',710],['pear',1020],['apple',1390],['carrot',1770],['pear',2110]].map(([type,x])=>makeEnemy(type,x));}
if(n===2){enemies=[['carrot',350],['pear',650],['apple',930],['carrot',1220],['pear',1590],['apple',2010]].map(([type,x])=>makeEnemy(type,x));}
if(n===3){enemies=[['apple',420],['carrot',900],['pear',1440]].map(([type,x])=>makeEnemy(type,x));boss={x:worldW-360,y:GR-112,w:72,h:112,hp:8,max:8,vx:1.6,hit:0,attack:0};}
for(let i=0;i<9;i++)candies.push({x:210+i*255+rand(-20,25),y:GR-50-rand(0,110),taken:false,phase:rand(0,6)});
gate={x:worldW-100,y:GR-85};notice=n===3?'DUMDUM’S HAUNTED ORCHARD!':'LEVEL '+n+' · THE ORCHARD TRAIL';noticeT=150;
}
function makeEnemy(type,x){return{x,y:GR-39,w:38,h:39,type,vx:rand(.6,1)*(Math.random()<.5?-1:1),alive:true,hit:0,base:x};}
function start(){score=0;lives=3;makeLevel(1);state='play';}
function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function ellipse(x,y,rx,ry,c){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=c;ctx.fill();}
function line(x1,y1,x2,y2,c,w=2){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.stroke();}
function text(s,x,y,size,color='#fff',align='center',weight=800){ctx.font=`${weight} ${size}px 'Baloo 2',sans-serif`;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(s,x,y);}
function puff(x,y,c,n=8){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-2.8,2.8),vy:rand(-4,-.2),life:rand(22,42),c,size:rand(3,7)});}
function roundedShadow(x,y,w,h,r,c){ctx.shadowColor='#18283c55';ctx.shadowBlur=8;ctx.shadowOffsetY=4;roundRect(x,y,w,h,r,c);ctx.shadowBlur=0;ctx.shadowOffsetY=0;}
function drawCloud(x,y,s){ctx.fillStyle='#ffffffa8';ctx.beginPath();ctx.ellipse(x,y,40*s,14*s,0,0,7);ctx.ellipse(x-20*s,y-7*s,19*s,17*s,0,0,7);ctx.ellipse(x+5*s,y-14*s,23*s,22*s,0,0,7);ctx.ellipse(x+27*s,y-6*s,20*s,16*s,0,0,7);ctx.fill();}
function background(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#83d6e2');g.addColorStop(.63,'#d9f3d9');g.addColorStop(1,'#ffdea0');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// sun and drifting clouds
ellipse(790,115,53,53,'#ffe89a');for(let i=0;i<5;i++){let x=((i*245-frame*.22)%(W+180)+W+180)%(W+180)-60;drawCloud(x,90+(i%3)*49,.7+(i%2)*.22);}
// distant orchard hills
ctx.fillStyle='#9dcfae';ctx.beginPath();ctx.moveTo(0,365);for(let x=0;x<=W+40;x+=40)ctx.lineTo(x,320+Math.sin((x+cam*.12)/105)*22+Math.cos((x+cam*.12)/53)*10);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
// distant trees
for(let i=-1;i<12;i++){let x=((i*112-cam*.25)%(W+130)+W+130)%(W+130)-45;ellipse(x,354,33,38,'#78bc91');roundRect(x-5,350,10,37,4,'#a87554');ellipse(x-13,342,5,5,'#ffdf78');ellipse(x+15,355,5,5,'#ffdf78');}
// rolling foreground edge
ctx.fillStyle='#8cc985';ctx.beginPath();ctx.moveTo(0,432);for(let x=0;x<=W+20;x+=20)ctx.lineTo(x,421+Math.sin((x+cam*.42)/72)*7);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();}
function drawWorld(){background();ctx.save();ctx.translate(-cam,0);
// platforms
for(const p of platforms){if(p.type==='ground'){ctx.fillStyle='#a9784e';ctx.fillRect(p.x,p.y,p.w,p.h);ctx.fillStyle='#75c779';ctx.fillRect(p.x,p.y,p.w,13);ctx.fillStyle='#54aa69';for(let x=p.x;x<p.x+p.w;x+=26){ctx.beginPath();ctx.moveTo(x,p.y+13);ctx.lineTo(x+8,p.y+5);ctx.lineTo(x+13,p.y+13);ctx.fill();}for(let x=p.x+12;x<p.x+p.w;x+=41){ellipse(x,p.y+37,3,3,'#d59c63');ellipse(x+18,p.y+72,2,2,'#d59c63');}}
else{roundedShadow(p.x,p.y,p.w,p.h,8,'#9b6849');roundRect(p.x,p.y,p.w,p.h-5,8,'#73c982');ctx.fillStyle='#b8e889';ctx.fillRect(p.x+8,p.y+3,p.w-16,4);}}
// collectibles
for(const c of candies)if(!c.taken){let bob=Math.sin(frame*.08+c.phase)*5,x=c.x,y=c.y+bob;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(frame*.045+c.phase)*.15);ctx.fillStyle='#fff';ctx.beginPath();ctx.moveTo(-19,0);ctx.lineTo(-27,-9);ctx.lineTo(-23,0);ctx.lineTo(-27,9);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(19,0);ctx.lineTo(27,-9);ctx.lineTo(23,0);ctx.lineTo(27,9);ctx.closePath();ctx.fill();ellipse(0,0,19,14,'#f77b91');ellipse(-5,-4,5,4,'#ffb1b8');ellipse(5,3,2,2,'#8e3d68');ellipse(11,3,2,2,'#8e3d68');ctx.restore();}
for(const e of enemies)if(e.alive)drawEnemy(e);
if(boss)drawBoss();
for(const s of shots){ellipse(s.x,s.y,10,8,'#ffb8cb');ellipse(s.x-2,s.y-3,3,2,'#fff2d6');}
drawPlayer();
// goal arch
if(gate){roundRect(gate.x,gate.y,53,85,25,'#4eaa7a');roundRect(gate.x+7,gate.y+7,39,78,20,'#fff0ac');ellipse(gate.x+27,gate.y+42,13,22,'#7fd8a4');text('★',gate.x+27,gate.y+43,18,'#fff4bf');}
ctx.restore();
for(const p of particles){ellipse(p.x,p.y,p.size,p.size,p.c);}
}

