function drawEnemy(e){let x=e.x,y=e.y+(e.hit?Math.sin(frame)*2:0);ctx.save();ctx.translate(x+e.w/2,y+e.h/2);if(e.vx<0)ctx.scale(-1,1);
if(e.type==='apple'){ellipse(0,4,18,19,'#ef6d62');ellipse(-5,-3,6,6,'#ff9b72');line(1,-14,3,-23,'#76503b',4);ellipse(9,-20,8,4,'#67bd72');}
else if(e.type==='pear'){ellipse(0,6,15,20,'#a4cf58');ellipse(0,-6,9,13,'#b8da67');line(0,-18,2,-25,'#76503b',4);ellipse(7,-24,8,4,'#64b66d');}
else{roundRect(-13,-12,26,32,12,'#ff9a54');ctx.beginPath();ctx.moveTo(-12,-9);ctx.lineTo(-4,-25);ctx.lineTo(1,-14);ctx.lineTo(7,-30);ctx.lineTo(12,-10);ctx.fillStyle='#ff9a54';ctx.fill();line(3,-23,6,-29,'#71b965',4);}
ellipse(-6,2,2.4,4,'#29364b');ellipse(6,2,2.4,4,'#29364b');ctx.strokeStyle='#a84851';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,8,5,.1,2.9);ctx.stroke();ellipse(-14,28,8,4,'#34425a');ellipse(14,28,8,4,'#34425a');ctx.restore();}
function drawPlayer(){let p=player;let bob=p.ground?Math.sin(p.anim*.18)*1.5:0;let x=p.x,y=p.y+bob;ctx.save();ctx.translate(x+p.w/2,y);if(p.face<0)ctx.scale(-1,1);
if(p.inv>0&&Math.floor(frame/4)%2===0)ctx.globalAlpha=.48;
// trailing twin buddy
let buddyX=-22;ellipse(buddyX,48,13,4,'#4e8d70');roundRect(buddyX-10,23,20,20,6,'#ed7969');ellipse(buddyX,15,10,12,'#ffcfaa');for(let i=-1;i<=1;i++)ellipse(buddyX+i*6,7,5,5,'#754a36');ellipse(buddyX-3,16,1.3,2,'#263448');ellipse(buddyX+3,16,1.3,2,'#263448');roundRect(buddyX-8,41,7,9,3,'#6789bd');roundRect(buddyX+2,41,7,9,3,'#6789bd');
// legs, sneakers
let stride=p.ground?Math.sin(p.anim*.25)*3:0;roundRect(-11,40+stride,9,12,4,'#4d6e9a');roundRect(2,40-stride,9,12,4,'#4d6e9a');roundRect(-14,49+stride,14,6,3,'#fff5dc');roundRect(1,49-stride,14,6,3,'#fff5dc');
// shirt and shorts
roundRect(-14,18,28,26,8,'#ff8b67');roundRect(-12,36,24,10,4,'#536fa5');line(-4,22,3,33,'#ffd56a',3);roundRect(-16,23,7,17,4,'#ffbb90');
// neck/head
roundRect(-5,12,10,9,4,'#f5ba91');ellipse(0,6,15,16,'#ffd0a9');
// curls cap of brown curls
for(let i=0;i<5;i++){let cx=-12+i*6;ellipse(cx, -5+Math.abs(i-2)*1.2,6,7,'#704833');}ellipse(-15,1,5,5,'#704833');ellipse(13,-1,5,5,'#704833');
// ear, face
ellipse(14,7,3.5,4,'#f2b28d');ellipse(5,6,2,3,'#25354a');ellipse(5.5,5,0.7,1,'#fff');ctx.strokeStyle='#b86654';ctx.lineWidth=1.6;ctx.beginPath();ctx.arc(5,13,4,0.1,1.7);ctx.stroke();
// candy puff wind-up
if(p.attack>0){ellipse(25,27,6+p.attack*.2,6+p.attack*.2,'#ffe695');ellipse(25,27,2,2,'#fff');}
ctx.restore();}
function drawBoss(){let b=boss;let x=b.x,y=b.y+Math.sin(frame*.05)*5;ctx.save();ctx.translate(x+b.w/2,y);if(b.vx<0)ctx.scale(-1,1);if(b.hit>0)ctx.globalAlpha=.5;
// floaty sheet scallops
ctx.fillStyle='#f8f2e7';ctx.beginPath();ctx.moveTo(-35,14);ctx.quadraticCurveTo(-40,-39,0,-43);ctx.quadraticCurveTo(41,-37,35,14);ctx.lineTo(35,47);ctx.quadraticCurveTo(26,38,18,48);ctx.quadraticCurveTo(9,39,0,49);ctx.quadraticCurveTo(-10,39,-18,48);ctx.quadraticCurveTo(-28,39,-35,47);ctx.closePath();ctx.fill();ctx.strokeStyle='#c9d2d7';ctx.lineWidth=2;ctx.stroke();
// top hat
roundRect(-31,-47,62,9,4,'#35415b');roundRect(-21,-75,42,30,7,'#29344d');roundRect(-21,-53,42,5,2,'#e7ae56');
// face
ellipse(-10,-8,3,5,'#35415b');ellipse(10,-8,3,5,'#35415b');ellipse(0,6,5,6,'#e99c88');ctx.restore();}
function hud(){// top left level card
roundedShadow(22,20,205,68,18,'#fff9e9');ellipse(48,53,18,18,'#f3c55f');text('★',48,53,20,'#fff');text('LEVEL '+String(level).padStart(2,'0'),77,43,14,'#5d6880','left',900);text('ORCHARD ODYSSEY',77,64,15,'#253751','left',900);
roundedShadow(242,20,118,48,16,'#fff9e9');text('✦  '+String(score).padStart(4,'0'),301,44,19,'#df805d');
