function hurt(){if(player.inv>0||state!=='play')return;lives--;player.inv=110;player.vy=-7;player.vx=-player.face*4;puff(player.x+16,player.y+22,'#fff0c4',11);if(lives<=0){state='over';}else{notice='OOPS! THE TWINS KEEP GOING!';noticeT=90;}}
