if(left){p.vx-=.65;p.face=-1;}if(right){p.vx+=.65;p.face=1;}p.vx*=p.ground?.79:.92;p.vx=clamp(p.vx,-4.5,4.5);if(!left&&!right&&Math.abs(p.vx)<.18)p.vx=0;
if(jump&&(pressed.jump||pressed.w||pressed.arrowup||pressed[' '])&&p.ground){p.vy=-12.3;p.ground=false;puff(p.x+17,p.y+52,'#d7f0c2',5);}
p.vy+=.56;p.vy=Math.min(p.vy,12);p.x+=p.vx;p.x=clamp(p.x,0,worldW-p.w);p.y+=p.vy;p.ground=false;
for(const q of platforms)if(p.x+p.w>q.x&&p.x<q.x+q.w&&p.y+p.h>=q.y&&p.y+p.h-p.vy<=q.y+8&&p.vy>=0){p.y=q.y-p.h;p.vy=0;p.ground=true;}
if(p.y>H+80){hurt();p.y=GR-70;p.vy=0;}
if(p.inv>0)p.inv--;if(p.sugar>0)p.sugar--;
if(attack&&p.attack<=0){p.attack=16;shots.push({x:p.x+(p.face>0?42:-8),y:p.y+29,vx:p.face*(p.sugar>0?9:7),life:90});}
if(p.attack>0)p.attack--;
for(const s of shots){s.x+=s.vx;s.life--;for(const e of enemies)if(e.alive&&Math.abs(s.x-(e.x+e.w/2))<24&&Math.abs(s.y-(e.y+e.h/2))<25){e.alive=false;s.life=0;score+=100;puff(e.x+18,e.y+18,'#ffb3a5',12);}if(boss&&Math.abs(s.x-(boss.x+boss.w/2))<40&&Math.abs(s.y-(boss.y+boss.h/2))<50){boss.hp--;boss.hit=10;s.life=0;score+=50;shake=5;puff(s.x,s.y,'#ead6ff',7);if(boss.hp<=0){puff(boss.x+36,boss.y+45,'#f8f2e7',24);boss=null;gate={x:worldW-100,y:GR-85};notice='DUMDUM DEFEATED! FIND THE GATE!';noticeT=140;}}}
shots=shots.filter(s=>s.life>0&&s.x>-50&&s.x<worldW+50);
for(const e of enemies)if(e.alive){e.x+=e.vx;if(Math.abs(e.x-e.base)>75)e.vx*=-1;e.hit=Math.max(0,e.hit-1);if(overlap(p,e)){if(p.vy>1&&p.y+p.h-e.y<19){e.alive=false;p.vy=-8;score+=100;puff(e.x+18,e.y+15,'#ffbd91',10);}else hurt();}}
for(const c of candies)if(!c.taken&&Math.abs((p.x+p.w/2)-c.x)<29&&Math.abs((p.y+p.h/2)-c.y)<35){c.taken=true;score+=250;p.sugar=600;puff(c.x,c.y,'#ffbdd0',14);notice='SUGAR RUSH! EXTRA-POWERFUL PUFFS!';noticeT=100;}
if(boss){boss.x+=boss.vx;if(boss.x<worldW-600||boss.x>worldW-130)boss.vx*=-1;if(boss.hit>0)boss.hit--;boss.attack++;if(boss.attack>95){boss.attack=0;hostile.push({x:boss.x+36,y:boss.y+42,vx:(p.x-boss.x)*.012,vy:2.1,life:160});}if(overlap(p,boss)){if(p.vy>0&&p.y+p.h<boss.y+35){boss.hp--;boss.hit=14;p.vy=-9;shake=7;puff(p.x+15,p.y+40,'#e6d5ff',8);if(boss.hp<=0){score+=1000;boss=null;gate={x:worldW-100,y:GR-85};notice='DUMDUM DEFEATED! FIND THE GATE!';noticeT=140;}}else hurt();}}
