function draw(){ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);ctx.clearRect(0,0,W,H);if(state==='title'&&!player.x)makeLevel(1);ctx.save();if(shake&&state==='play')ctx.translate(rand(-shake,shake),rand(-shake,shake));drawWorld();if(state!=='title')hud();ctx.restore();drawOverlay();}
let audio=null;function beep(f=440,d=.08,type='sine'){if(muted)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d);}catch(e){}}
function togglePause(){if(state==='play')state='pause';else if(state==='pause')state='play';}
document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' ','arrowdown'].includes(k))e.preventDefault();if(!keys[k])pressed[k]=true;keys[k]=true;if(k==='p'||k==='escape')togglePause();if(k==='enter'&&(state==='title'||state==='over'||state==='win'))start();});
document.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});window.addEventListener('blur',()=>{keys={};if(state==='play')state='pause';});
canvas.addEventListener('pointerdown',()=>{if(state==='title'||state==='over'||state==='win')start();});
document.querySelector('#pause').addEventListener('click',togglePause);
document.querySelector('#sound').addEventListener('click',e=>{muted=!muted;e.currentTarget.textContent=muted?'♫̸':'♫';if(!muted)beep(600,.08);});
for(const b of document.querySelectorAll('.touchbtn')){let key=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(key==='jump'&&!keys.jump)pressed.jump=true;keys[key]=true;if(key==='attack')beep(520,.05);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{e.preventDefault();keys[key]=false;});}
let last=0;function loop(t){let dt=Math.min(40,t-last||16);last=t;if(dt>0)update();draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
</script></body></html>

